<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';require_once __DIR__.'/app/lib/Entitlements.php';$pdo=Db::pdo();Security::start();$u=Security::user();if(!$u){header('Location: /login?next='.rawurlencode('/decision-pack'));exit;}$ctx=Entitlements::context($pdo,$u);$csrf=Security::csrf();$pro=!empty($ctx['features']['decision_pack']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Software Decision Pack | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;background:#f6f8fb;color:#14213d;margin:0}main{max-width:1100px;margin:auto;padding:24px}.card{background:#fff;border:1px solid #e4e9f0;border-radius:14px;padding:18px;margin-bottom:16px}input,textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd5e1;border-radius:8px}textarea{min-height:110px}button{border:0;border-radius:8px;padding:10px 14px;background:#1d4ed8;color:#fff}.muted{color:#64748b}.missing{background:#fff7ed;padding:10px;border-radius:8px}.section{border-top:1px solid #e5e7eb;padding-top:14px;margin-top:14px}pre{white-space:pre-wrap;word-break:break-word}@media print{button,.editor{display:none}body{background:#fff}.card{border:0}}</style></head><body><main><h1>Software Decision Pack</h1><p class="muted">Management-ready decision support for procurement handoff. This does not create requisitions, POs, contracts or approvals.</p><div class="card editor"><label>Selection project ID</label><input id="pid" type="number" value="<?=htmlspecialchars($_GET['project_id']??'')?>"><label>Executive summary override</label><textarea id="exec"></textarea><label>Risks & assumptions</label><textarea id="risks"></textarea><label>Recommendation narrative</label><textarea id="rec"></textarea><p><button onclick="loadPack(false)"><?=$pro?'Generate decision pack':'Preview decision pack'?></button><?php if($pro): ?> <button onclick="window.print()">Print / Save as PDF</button><?php endif; ?></p><p class="muted"><?=$pro?'Pro: full generation enabled.':'Registered preview: upgrade to Pro for the full management-ready pack.'?></p></div><div id="out"></div></main><script>const csrf=<?=json_encode($csrf)?>,pro=<?=$pro?'true':'false'?>;function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}async function loadPack(){let id=+document.getElementById('pid').value;if(!id)return;let url='/api/decision-packs?project_id='+id,opt={headers:{'X-CSRF-Token':csrf,'Content-Type':'application/json'}};if(pro){opt.method='POST';opt.body=JSON.stringify({narrative:{executive_summary:document.getElementById('exec').value,risks_assumptions:document.getElementById('risks').value,recommendation:document.getElementById('rec').value}})}let r=await fetch(url,opt),d=await r.json();if(!r.ok){document.getElementById('out').innerHTML='<div class="card">'+esc(d.error||'request_failed')+'</div>';return}render(d.decision_pack)}function render(p){let html='<div class="card"><h2>'+esc(p.project?.name||p.project?.title||'Decision Pack')+'</h2>';if(p.preview)html+='<p class="missing"><strong>Preview only.</strong> Full pack is a Pro feature.</p>';if((p.missing_data||[]).length)html+='<p class="missing"><strong>Missing / assumptions disclosed:</strong> '+p.missing_data.map(esc).join(', ')+'</p>';for(const [k,v] of Object.entries(p.sections||{})){html+='<div class="section"><h2>'+esc(k.replaceAll('_',' '))+'</h2><p class="muted">Source: '+esc(v.source||'')+'</p>';if(v.content)html+='<p>'+esc(v.content)+'</p>';if(v.narrative)html+='<p>'+esc(v.narrative)+'</p>';if(v.preferred)html+='<pre>'+esc(JSON.stringify(v.preferred,null,2))+'</pre>';if(v.items)html+='<pre>'+esc(JSON.stringify(v.items,null,2))+'</pre>';if(v.legend)html+='<pre>'+esc(JSON.stringify(v.legend,null,2))+'</pre>';html+='</div>'}html+='</div>';document.getElementById('out').innerHTML=html}if(document.getElementById('pid').value)loadPack();</script></body></html>